-- Auditoria de metadados apenas: não executa RPCs, lê usuários ou modifica migrations/dados.
select jsonb_build_object(
 'migration_registry',(select jsonb_agg(jsonb_build_object('version',version,'name',name)) from supabase_migrations.schema_migrations),
 'functions',(select jsonb_agg(jsonb_build_object('name',p.proname,'arguments',pg_get_function_identity_arguments(p.oid),'result',pg_get_function_result(p.oid),'security_definer',p.prosecdef,'config',p.proconfig,'source_md5',md5(p.prosrc),'authenticated_execute',has_function_privilege('authenticated',p.oid,'execute'),'anon_execute',has_function_privilege('anon',p.oid,'execute'))) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('get_my_account_profile','complete_my_profile','complete_vendor_onboarding','append_my_vendor_products','request_account_deletion','discover_vendors','get_my_interest_state','create_purchase_intent','cancel_purchase_intent','get_route_attendance','set_route_availability','register_interest_push_device','revoke_interest_push_device','verify_interest_push','publish_route_location')),
 'tables',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'name',c.relname,'rls',c.relrowsecurity,'anon_select',has_table_privilege('anon',c.oid,'select'),'authenticated_select',has_table_privilege('authenticated',c.oid,'select'))) from pg_class c join pg_namespace n on n.oid=c.relnamespace where c.relkind='r' and ((n.nspname='public' and c.relname in ('profiles','vendors','products','vendor_locations','vendor_routes','purchase_intents')) or (n.nspname='private' and c.relname in ('interest_push_devices','interest_push_outbox','account_deletion_requests')))),
 'triggers',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'name',t.tgname,'enabled',t.tgenabled,'function_schema',pn.nspname,'function',p.proname)) from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace join pg_proc p on p.oid=t.tgfoid join pg_namespace pn on pn.oid=p.pronamespace where not t.tgisinternal and ((n.nspname='auth' and c.relname='users') or (n.nspname='public' and c.relname in ('vendor_routes','purchase_intents')))),
 'realtime',(select jsonb_agg(tablename) from pg_publication_tables where pubname='supabase_realtime' and schemaname='public'),
 'policy_count',(select count(*) from pg_policies where schemaname='public' and tablename in ('profiles','vendors','products','vendor_locations','vendor_routes','purchase_intents'))
) as audit;
